import {STUDIO_URL,publicStatus,publicEvents,trackLabel,trackTypeLabel,trackHistoryLabel,deadline,projectOwner,eventLayout,publicEventStatus,SCRIPT_NOTICE,VIDEO_NOTICE,VIDEO_SUPPORT_NOTICE,isPlatformProject,platformOutputs} from './config.js?v=20261026-v1';
import {createEventViews} from './event-views.js?v=20261026-v1';
import {TRACKS,TODAY,USER,KEY,uid,time,seed,load,save,eventBy,workBy,gate,submitWork,reviewWork,reviewFeedback,credit,cancelEvent,publishResults,storeFiles,getFile,validateEvent} from './model.js?v=20261026-v1';
let eventView='';
let state=load(), filters={}, lastFocus, modalCleanup, attached=[], selectedProject='', editing='', selectedOutput='', projectQuery='', videoSource='platform', busy=false;
const app=document.querySelector('#app'), root=document.querySelector('#modal-root');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n||0).toLocaleString('zh-CN');
const size=n=>n>1048576?(n/1048576).toFixed(1)+' MB':Math.max(1,Math.round(n/1024))+' KB';
const button=(label,action='',cls='',extra='')=>`<button type="button" class="btn ${cls}" ${action?`data-action="${action}"`:''} ${extra}>${label}</button>`;
const link=(label,to,cls='')=>`<a class="${cls}" href="#/${to}">${label}</a>`;
const tag=(label)=>`<span class="tag ${['征集中','正在进行','已通过','已完成'].includes(label)?'green':['待初审','待复审','评审中','审核中'].includes(label)?'amber':['已取消','未通过'].includes(label)?'red':''}">${esc(trackTypeLabel(label))}</span>`;
const options=(items,value,all='')=>(all?`<option value="">${all}</option>`:'')+items.map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${esc(trackTypeLabel(x))}</option>`).join('');
const field=(label,control,full='')=>`<label class="field ${full}"><span>${label}</span>${control}</label>`;
const input=(name,value='',placeholder='',required=false,type='text')=>`<input name="${name}" value="${esc(value)}" placeholder="${placeholder}" ${required?'required':''} type="${type}">`;
const textarea=(name,value='',placeholder='',required=false)=>`<textarea name="${name}" rows="4" placeholder="${placeholder}" ${required?'required':''}>${esc(value)}</textarea>`;
const empty=text=>`<div class="empty"><span>◇</span><h3>${text}</h3><p>试试其他筛选条件，或发起一次新的创作。</p></div>`;
const persist=()=>save(state);
function toast(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),3500);}
function closeModal(){if(modalCleanup)modalCleanup();modalCleanup=null;root.innerHTML='';document.body.classList.remove('locked');lastFocus?.focus();}
function modal(title,body,footer='',wide=false){closeModal();lastFocus=document.activeElement;root.innerHTML=`<div class="overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header><h2 id="modal-title">${title}</h2>${button('×','close','icon','aria-label="关闭弹窗"')}</header><div class="modal-body">${body}</div>${footer?`<footer>${footer}</footer>`:''}</section></div>`;document.body.classList.add('locked');setTimeout(()=>root.querySelector('input,select,textarea,button')?.focus(),10);}
function confirm(title,text,fn,label='确认'){modal(title,`<p class="confirm-copy">${esc(text)}</p><div class="form-error" role="alert"></div>`,button('取消','close')+button(label,'confirm','primary'));root.querySelector('[data-action="confirm"]').onclick=()=>{try{fn();persist();closeModal();render();toast('操作成功');}catch(e){root.querySelector('.form-error').textContent=e.message;}};}
function bindForm(id,fn){document.getElementById(id)?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,err=f.querySelector('.form-error');if(busy)return;busy=true;const submit=e.submitter;if(submit)submit.disabled=true;try{await fn(Object.fromEntries(new FormData(f)),f,e.submitter);persist();}catch(error){if(err)err.textContent=error.message;else toast(error.message);}finally{busy=false;if(submit)submit.disabled=false;}});}
function demoBar(admin=false){return `<aside class="demo-bar"><span class="demo-dot"></span><span>交互演示 · 示例数据</span><span class="demo-date">2026.10.26</span><a href="#/${admin?'events':'admin/events'}">切换到${admin?'官网':'绿台'} ↗</a>${button('重置','reset','text')}</aside>`;}
function front(content,active='events'){document.body.className='front'+(root.innerHTML?' locked':'');app.innerHTML=`<header class="site-header"><a href="#/events" class="logo"><img src="./assets/logo.png" alt="容量万相"></a><nav><a href="../wanxiang-requirements-20260914/index.html">首页</a><a href="../wanxiang-requirements-20260914/index.html#novel">小说IP库</a><a href="../wanxiang-requirements-20260914/index.html#script">剧本库</a><a href="../ecology-innovation-center-v3/prototype/index.html">生态创新中心 <small class="contest-badge">赛</small></a><span></span><a href="${STUDIO_URL}" target="_blank" rel="noopener noreferrer">漫剧制作 <small>HOT</small></a></nav><div class="header-user">${button('◇ '+money(state.balance),'wallet','balance')}<span class="avatar">林</span></div></header><div class="ecosystem-nav"><div class="container"><a href="../ecology-innovation-center-v3/prototype/index.html">生态创新中心</a><span>/</span><strong>创作大赛</strong><div class="sub-links">${link('赛事广场','events',active==='events'?'active':'')}${link('我的赛事','mine',active==='mine'?'active':'')}</div></div></div><main class="container">${content}</main><footer class="site-footer"><span>容量万相 · 让每一份想象成为作品</span><span>本原型仅作交互演示，赛事、奖金及人物为示例</span></footer>${demoBar()}`;}
function eventCard(e){return `<a class="event-card" href="#/event/${e.id}"><div class="event-cover"><img src="./assets/${e.image}" alt="${esc(e.region)}创作主题视觉">${tag(publicEventStatus(e))}<span class="region">${esc(e.region)}</span></div><div class="card-body"><div class="eyebrow"><span>${e.tracks.length} 个开放赛道</span></div><h3>${esc(e.title)}</h3><p class="event-card-intro">${esc(e.subtitle)}</p><div class="event-track-tags">${e.tracks.map(t=>'<span>'+esc(trackLabel(t))+'</span>').join('')}</div><dl class="event-card-facts"><div><dt>比赛时间</dt><dd>${esc(e.date)}</dd></div><div><dt>主办单位</dt><dd>${esc(e.host)}</dd></div></dl><div class="card-bottom"><span>${esc(e.rewardSummary)}</span><b>查看赛事 <i>↗</i></b></div></div></a>`;}
function eventsPage(){
  const visible=publicEvents(state),hero=visible.find(e=>e.status==='征集中')||visible[0],layout=eventLayout(visible.length,eventView);
  if(!hero){front(empty('暂无已发布赛事'));return;}
  const filtered=visible.filter(e=>(!filters.status||publicEventStatus(e)===filters.status)&&(!filters.track||e.tracks.some(t=>t.name===filters.track))&&(!filters.q||(e.title+e.region+e.host).includes(filters.q)));
  front(`<section class="hero contest-hero"><img src="./assets/${hero.image}" alt="山海主题创作场景"><div class="hero-shade"></div><div class="hero-copy"><div class="hero-kicker"><span></span> ${esc(publicEventStatus(hero))} · 2026 创作大赛</div><h1>${esc(hero.title.split(' · ')[0])}<br><span>${esc(hero.title.split(' · ')[1]||'创作大赛')}</span></h1><p>${esc(hero.subtitle)}</p><div class="hero-actions">${link('查看赛事 &nbsp; ↗','event/'+hero.id,'btn primary')}</div></div><div class="hero-side"><span>创意从这里发生</span><b>故事 · 光影 · 想象</b></div></section><section class="events-section"><div class="section-heading"><div><span class="overline">CREATIVE COMPETITIONS</span><h2>发现你的下一场创作</h2></div>${link('查看我的参赛作品 →','mine','muted-link')}</div><div class="list-toolbar"><div class="filter-tabs">${['全部赛事','即将开始','正在进行','征集结束'].map((s,i)=>button(s,'event-filter',(!filters.status&&i===0)||filters.status===s?'active':'',`data-value="${i?s:''}"`)).join('')}</div><div class="search-controls"><select id="track-filter" aria-label="按赛道筛选">${options(TRACKS,filters.track,'全部赛道')}</select><form id="search-events"><input name="q" value="${esc(filters.q||'')}" placeholder="搜索赛事" aria-label="搜索赛事"><button aria-label="搜索" type="submit">⌕</button></form></div></div><div class="event-list-heading"><span>共 <b>${filtered.length}</b> 场赛事</span><div class="event-view-switch" role="group" aria-label="赛事展示方式">${button('☰ 横向','event-view',layout==='wide'?'active':'',`data-value="wide" aria-pressed="${layout==='wide'}"`)}${button('▦ 卡片','event-view',layout==='grid'?'active':'',`data-value="grid" aria-pressed="${layout==='grid'}"`)}</div></div><div class="events-grid ${layout==='wide'?'events-wide':''}">${filtered.map(eventCard).join('')||empty('暂无符合条件的赛事')}</div></section><div class="creation-banner"><div><span class="overline">FROM STORY TO SCREEN</span><h2>让你的创作，走向下一场比赛。</h2><p>在容量万相漫剧制作平台完成作品，再选择项目中的视频参赛。</p></div><a class="btn" href="${STUDIO_URL}" target="_blank" rel="noopener noreferrer">没有作品？前往漫剧制作 ↗</a></div>`);
  document.querySelector('#track-filter').onchange=e=>{filters.track=e.target.value;eventsPage();};
  document.querySelector('#search-events').onsubmit=e=>{e.preventDefault();filters.q=new FormData(e.target).get('q').trim();eventsPage();};
}
function eventPage(id){
  const e=eventBy(state,id);if(!e||e.status==='草稿'){front(empty('赛事暂未发布'));return;}
  if(e.status==='已取消'){front('<div class="page-heading"><h1>赛事已取消</h1></div><div class="notice danger">'+esc(e.cancelReason||'本次赛事已终止')+'</div><p>已提交的作品可在「我的赛事」查看；积分由业务人工处理。</p>'+link('返回赛事广场','events','btn')+' '+link('查看我的赛事','mine','btn'));return;}
  const section=filters.detail||'赛道与规则';
  const tracksHTML=e.tracks.map((t,i)=>{const err=gate(state,e.id,t.name);return '<article class="track-card"><div class="track-number">0'+(i+1)+'</div><div><span class="track-type">'+esc(trackTypeLabel(t.name))+'</span><h3>'+esc(trackLabel(t))+'</h3><p>'+esc(t.brief)+'</p><div class="track-materials"><b>提交材料</b><p>'+esc(t.requirements)+'</p></div><small>投稿时间：'+t.start+' — '+t.end+'</small></div><div>'+(err?button(TODAY<t.start?'即将开放':TODAY>t.end?'已截止':e.status!=='征集中'?publicEventStatus(e):'暂不可参赛','','disabled','disabled title="'+esc(err)+'"'):link('立即参赛 →','submit/'+e.id+'/'+TRACKS.indexOf(t.name),'btn primary'))+(err?'<small class="gate-reason">'+esc(err)+'</small>':'')+'</div></article>';}).join('');
  const body=section==='赛道与规则'?'<h2>赛事介绍</h2><div class="event-intro">'+e.intro.split('\n').filter(Boolean).map(p=>'<p>'+esc(p)+'</p>').join('')+'</div><div class="mode-note">'+(e.tracks.length===1?'本赛事仅开放以下赛道。':'各赛道独立参赛，可参加多个赛道。')+'每场赛事每个赛道最多提交 5 件作品。</div><h2>'+(e.tracks.length===1?'本次开放赛道':'选择你的创作赛道')+'</h2><div class="track-list">'+tracksHTML+'</div><h2>参赛须知</h2><ul class="readable"><li>个人、团队、企业及其他主体均可参加，不限制参加赛事数量。</li><li>剧本通过本地上传；漫剧样片和成片可选择容量万相平台已完成作品，或上传外部平台制作的视频。</li><li>作品版权归作者所有，请确保原创或具备参赛授权。</li><li>投稿截止后进入评选；未通过为最终结果，不开放修改重投。</li></ul>':section==='赛事安排'?extraViews.schedule(e):section==='奖项与支持'?extraViews.rewards(e):section==='创作资料'?extraViews.resources(e):null;
  front('<div class="breadcrumb">'+link('赛事广场','events')+' / '+esc(e.title)+'</div><section class="detail-hero"><img src="./assets/'+e.image+'" alt="'+esc(e.region)+'赛事主题"><div class="hero-shade"></div><div class="detail-title">'+tag(publicEventStatus(e))+'<h1>'+esc(e.title)+'</h1><p>'+esc(e.subtitle)+'</p><div class="detail-meta"><span>'+e.tracks.length+' 个开放赛道</span><span>投稿截止：'+deadline(e)+' 23:59（北京时间）</span></div></div></section><div class="detail-layout"><div><nav class="section-tabs">'+['赛道与规则','赛事安排','奖项与支持','创作资料','作品与结果'].map(s=>button(s,'detail-tab',section===s?'active':'','data-value="'+s+'"')).join('')+'</nav>'+(body!==null?'<section class="content-section">'+body+'</section>':publicResults(e))+'</div><aside class="detail-aside"><div class="side-card"><span class="overline">CREATIVE PARTNERS</span><h3>组织单位</h3><div class="organizer-item"><span>主办单位</span><p>'+esc(e.host)+'</p></div>'+(e.organizer?'<div class="organizer-item"><span>承办单位</span><p>'+esc(e.organizer)+'</p></div>':'')+(e.supporters?'<div class="organizer-item"><span>支持单位</span><p>'+esc(e.supporters)+'</p></div>':'')+'<hr><div class="fact"><span>参赛费用</span><b>免费参赛</b></div><div class="fact"><span>作品版权</span><b>归作者所有</b></div>'+button('咨询赛事商务','consult','', 'data-id="'+e.id+'"')+'</div><div class="side-card"><h3>让故事成为漫剧</h3><p>在容量万相完成制作后，可选择项目中的已完成视频参赛。</p><a class="btn" href="'+STUDIO_URL+'" target="_blank" rel="noopener noreferrer">没有作品？前往漫剧制作 ↗</a></div><div class="side-foot">已有参赛作品？<br>'+link('前往我的赛事 →','mine')+'</div></aside></div>');
}
function publicResults(e){if(!e.resultsPublished)return `<section class="content-section">${empty('作品与结果暂未公示')}<p class="center muted">评审完成、主办方确认后，将在这里展示公示作品与获奖名单。</p></section>`;const awards=state.awards.filter(a=>a.event===e.id);return `<section class="content-section"><span class="overline">OFFICIAL SELECTION</span><h2>获奖名单</h2><div class="result-list">${awards.map(a=>{const w=workBy(state,a.work);return `<article><span class="medal">✦</span><div><span class="gold">${esc(a.rank)} · ${esc(trackTypeLabel(w.track))}</span><h3>${esc(w.title)}</h3><p>作者：${esc(w.identity.entity)}</p><small>${a.cash?'现金 ¥'+money(a.cash):''} ${a.credits?' · '+money(a.credits)+' 积分':''} ${a.goods?' · '+esc(a.goods):''}</small></div>${button('查看作品','public-work','',`data-id="${w.id}"`)}</article>`;}).join('')}</div><h2>公示作品</h2><div class="showcase">${state.works.filter(w=>w.event===e.id&&w.public).map(w=>`<article>${tag(w.track)}<h3>${esc(w.title)}</h3><p>${esc(w.summary)}</p>${button('查看作品 →','public-work','text',`data-id="${w.id}"`)}</article>`).join('')}</div></section>`;}
function minePage(){const mine=state.works.filter(w=>w.user==='me');const shown=mine.filter(w=>(!filters.mine||publicStatus(w)===filters.mine)&&(!filters.event||w.event===filters.event));front(`<div class="page-heading"><div><span class="overline">MY COMPETITIONS</span><h1>我的赛事</h1><p>每一个故事的下一步，都在这里。</p></div>${link('发现更多赛事 ↗','events','btn primary')}</div><div class="mine-summary"><div><span>参赛作品</span><b>${mine.filter(w=>w.status!=='草稿').length}<small>件</small></b></div><div><span>审核中</span><b>${mine.filter(w=>w.status.startsWith('待')).length}<small>件</small></b></div><div><span>已通过</span><b>${mine.filter(w=>w.status==='已通过').length}<small>件</small></b></div><button data-action="wallet"><span>可用积分</span><b>${money(state.balance)} <small>查看明细 ↗</small></b></button></div><div class="list-toolbar"><div class="filter-tabs">${['全部作品','草稿','审核中','已通过','未通过'].map((s,i)=>button(s,'mine-filter',(!filters.mine&&i===0)||filters.mine===s?'active':'',`data-value="${i?s:''}"`)).join('')}</div><select id="mine-event" aria-label="按赛事筛选"><option value="">全部赛事</option>${state.events.filter(e=>mine.some(w=>w.event===e.id)).map(e=>`<option value="${e.id}" ${filters.event===e.id?'selected':''}>${esc(e.title)}</option>`).join('')}</select></div><div class="my-works">${shown.map(w=>{const e=eventBy(state,w.event),i=e.tracks.findIndex(t=>t.name===w.track),next=e.tracks[i+1];const a=state.awards.find(a=>a.work===w.id&&e.resultsPublished);return `<article><div class="work-art"><img src="./assets/${e.image}" alt="赛事主题"><span>${w.track==='剧本'?'文':'影'}</span></div><div class="my-work-main"><div class="row">${tag(e.status==='已取消'?'赛事已取消':publicStatus(w))}<span class="muted">${esc(trackTypeLabel(w.track))} · V${w.version}</span>${a?`<span class="gold">✦ ${esc(a.rank)}</span>`:''}</div><h3>${esc(w.title)}</h3><p>${esc(e.title)}</p><small class="muted">最近更新 ${w.updated}</small>${w.reason?`<p class="reject-note">${esc(w.reason)}</p>`:''}</div><div class="work-actions">${button('查看详情','work','',`data-id="${w.id}"`)}${w.status==='草稿'&&!gate(state,e.id,w.track,w.parent,w.id)?link('继续编辑',`edit/${w.id}`,'btn primary'):''}${w.status==='草稿'?button('删除草稿','delete-draft','text danger-text',`data-id="${w.id}"`):''}</div></article>`;}).join('')||empty('暂无参赛作品')}</div>`,'mine');document.querySelector('#mine-event').onchange=e=>{filters.event=e.target.value;minePage();};}
function filesHTML(files,removable=false){return files.map((f,i)=>`<div class="file-item"><span class="file-icon">${f.name.split('.').pop().slice(0,4).toUpperCase()}</span><div><b>${esc(f.name)}</b><small>${size(f.size)}${f.demo?' · 示例附件':''}</small></div>${removable?button('移除','remove-file','text',`data-index="${i}"`):button('查看','file','text',`data-file="${f.id}"`)}</div>`).join('');}
function submission(eventId,trackIndex,parent='',id=''){
  const e=eventBy(state,eventId),trackName=TRACKS[Number(trackIndex)],w=id&&workBy(state,id),isScript=trackName==='剧本';
  const err=gate(state,eventId,trackName,'',id);
  if(err){front(`<div class="page-heading"><h1>参赛作品</h1></div>${empty(err)}<p class="center">${link('返回赛事详情','event/'+eventId,'btn')}</p>`);return;}
  editing=id;attached=[...(w?.files||[])];
  const oldProject=w?.project&&state.projects.find(p=>p.id===w.project&&projectOwner(p)==='me');
  const oldOutput=oldProject&&platformOutputs(oldProject).find(o=>o.id===w.output);
  selectedProject=!isScript&&oldOutput?oldProject.id:'';selectedOutput=selectedProject?w.output:'';
  videoSource=w?.materialSource==='external'||(!selectedProject&&attached.length)?'external':'platform';
  const identity=w?.identity||USER,count=state.works.filter(x=>x.user==='me'&&x.event===eventId&&x.track===trackName).length,t=e.tracks.find(t=>t.name===trackName);
  const legacy=!!(w?.sourceScript||(!isScript&&w?.project&&!oldOutput));
  front(`<div class="breadcrumb">${link('赛事广场','events')} / ${link(esc(e.title),'event/'+e.id)} / 提交作品</div>
  <div class="page-heading compact"><div><span class="overline">SUBMIT YOUR WORK</span><h1>${w?'编辑参赛作品':'让你的故事被看见'}</h1><p>${esc(e.title)} · ${esc(trackLabel(t))}</p></div><span class="quota">本赛道已创建 <b>${count}</b> / 5 件作品</span></div>
  <div class="submit-layout"><form id="submission" class="form-panel" data-track-type="${isScript?'script':'video'}"><section><h2><span>01</span> 参赛信息</h2><div class="form-grid">
  ${field('参赛身份 *',`<select name="type">${options(['个人','团队','企业','机构','其他'],identity.type)}</select>`)}
  ${field('参赛主体名称 / 作者名称 *',input('entity',identity.entity,'填写个人、团队或单位名称',true))}
  ${field('联系人 *',input('name',identity.name,'请输入联系人',true))}
  ${field('联系电话 *',input('phone',identity.phone,'11 位手机号',false,'tel'))}
  ${field('联系微信',input('wechat',identity.wechat||'','请输入微信号（选填）'))}
  ${field('联系邮箱',input('email',identity.email,'接收赛事消息',false,'email'))}</div></section>
  <section><h2><span>02</span> 作品信息</h2><div class="form-grid">
  ${field('作品名称 *',`<input name="title" maxlength="60" value="${esc(w?.title||'')}" placeholder="为你的作品起个名字" required>`,'full')}
  ${field('作品简介 *',`<textarea name="summary" maxlength="2000" rows="4" placeholder="介绍故事主题、核心情节与创作亮点" required>${esc(w?.summary||'')}</textarea>`,'full')}</div>
  <label class="field"><span>参赛作品 *</span></label>
  ${legacy?'<div class="notice">投稿方式已调整，请按下方要求重新选择参赛材料。原草稿和历史材料仍保留。</div>':''}
  ${isScript?`<div class="submission-guidance"><b>剧本材料须知</b><p>${SCRIPT_NOTICE}</p></div><label class="upload-zone"><input type="file" id="upload" multiple><span class="upload-symbol">↑</span><strong>点击上传剧本文件，或将文件拖到此处</strong><small>支持 Word、PDF 等格式；文件仅保存在本机演示中</small></label><div id="file-list">${filesHTML(attached,true)}</div>`:videoMaterials(e)}
  </section><div class="agreement"><label><input name="agreed" type="checkbox" ${w?.agreed?'checked':''}> 我确认作品原创或已获授权，作品版权归作者所有，并同意赛事公示。</label>${button('查看参赛声明','terms','text')}</div>
  <div class="form-error" role="alert"></div><div class="form-actions">${link('取消','mine','btn')}<button class="btn" type="submit" value="draft" formnovalidate>保存草稿</button><button class="btn primary" type="submit" value="submit">提交参赛作品 →</button></div></form>
  <aside class="detail-aside"><div class="side-card"><h3>本赛道投稿要求</h3><p class="pre-line">${esc(t.requirements)}</p><div class="submission-deadline"><span>投稿截止</span><b>${t.end} 23:59</b><small>北京时间</small></div><h3>提交前，请确认</h3><ul class="readable"><li>参赛身份与联系方式准确</li><li>${isScript?'大纲、人物小传和正文完整':'已选择平台视频或上传外部作品'}</li><li>作品版权归作者所有</li><li>同场同赛道最多 5 件作品</li></ul><hr><p>提交后可在「我的赛事」查看审核进度。评选未通过不支持修改或重新投稿。</p></div></aside></div>`);
  bindUpload();
  bindForm('submission',async(d,f,submit)=>{
    const draft=submit.value==='draft';
    const local=isScript||videoSource==='external';
    submitWork(state,{id,event:eventId,track:trackName,title:d.title,summary:d.summary,identity:{type:d.type,entity:d.entity,name:d.name,phone:d.phone,wechat:d.wechat.trim(),email:d.email},materialSource:isScript?'script':videoSource,files:local?attached:[],project:local?'':selectedProject,output:local?'':selectedOutput,agreed:d.agreed==='on'},draft);
    persist();location.hash='#/mine';toast(draft?'草稿已保存':'作品已提交，审核中');
  });
}
function videoMaterials(e){return `<div class="video-materials"><div class="video-source-tabs" role="group" aria-label="参赛作品来源">${[['platform','选择万相平台作品'],['external','上传外部平台作品']].map(([value,label])=>button(label,'video-source',videoSource===value?'active':'',`data-value="${value}" aria-pressed="${videoSource===value}" aria-controls="video-${value}"`)).join('')}</div><p class="submission-source-note">两种方式任选其一，提交当前选中的参赛作品。</p><div id="video-platform" ${videoSource==='platform'?'':'hidden'}><div class="source-options">${button('＋ 选择容量万相平台作品','choose-project')}<span class="muted">选择本人项目中已完成的视频</span></div><div id="project-selection">${projectSelection()}</div></div><div id="video-external" ${videoSource==='external'?'':'hidden'}><label class="upload-zone"><input type="file" id="upload" multiple><span class="upload-symbol">↑</span><strong>点击上传视频文件，或将文件拖到此处</strong><small>上传外部平台制作的作品，支持 MP4 等视频格式</small><small>文件仅保存在本机演示中</small></label><div id="file-list">${filesHTML(attached,true)}</div></div><div class="video-support"><b>万相创作 · 积分扶持</b><p>${VIDEO_SUPPORT_NOTICE}</p><div class="support-actions"><a class="btn text" href="${STUDIO_URL}" target="_blank" rel="noopener noreferrer">没有作品？前往漫剧制作 ↗</a>${button('联系商务客服 →','consult','text',`data-id="${e.id}"`)}</div></div></div>`;}
function switchVideoSource(value){
  if(!['platform','external'].includes(value))return;
  videoSource=value;
  document.querySelectorAll('[data-action="video-source"]').forEach(el=>{const active=el.dataset.value===value;el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active));});
  document.querySelector('#video-platform').hidden=value!=='platform';
  document.querySelector('#video-external').hidden=value!=='external';
}
function projectSelection(){const p=state.projects.find(p=>p.id===selectedProject);return p?`<div class="selected-project"><span>▣</span><div><b>${esc(p.title)}</b><small>容量万相平台项目 · ${esc(p.outputs?.find(o=>o.id===selectedOutput)?.title||'请选择视频成果')}</small></div>${button('移除','remove-project','text')}</div>`:'';}
function bindUpload(){const u=document.querySelector('#upload'),zone=document.querySelector('.upload-zone');async function add(files){busy=true;try{const stored=await storeFiles([...files]);attached.push(...stored);document.querySelector('#file-list').innerHTML=filesHTML(attached,true);toast('文件已保存在本机');}catch(e){toast('文件保存失败，请检查浏览器存储空间');}finally{busy=false;u.value='';}}u.onchange=()=>add(u.files);zone.ondragover=e=>{e.preventDefault();zone.classList.add('drag');};zone.ondragleave=()=>zone.classList.remove('drag');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('drag');add(e.dataTransfer.files);};}
function reviewFeedbackHTML(w,admin=false){
  const notes=reviewFeedback(w);if(!notes.length)return '';
  return '<section class="review-feedback" aria-label="评审评语"><h3>评审评语</h3><div class="feedback-list">'+notes.map(n=>'<article><div class="feedback-meta">'+(admin?'<b>'+esc((n.stage?n.stage+' · ':'')+(n.result==='拒绝'?'未通过':'通过'))+'</b>':'')+'<time>'+esc(n.at)+'</time></div><p>'+esc(n.note)+'</p></article>').join('')+'</div></section>';
}
function workModal(id,isPublic=false){
  const w=workBy(state,id),e=eventBy(state,w?.event),admin=route()[0]==='admin';
  if(!w||!e||(!admin&&!isPublic&&w.user!=='me')){toast('无法查看该作品');return;}
  if(isPublic&&!w.public){toast('作品尚未公示');return;}
  const history=admin?w.history.filter(h=>!h.text.includes('晋级')):[{at:w.created,text:w.status==='草稿'?'作品草稿':'作品已提交'},...(w.status==='草稿'?[]:publicStatus(w)==='审核中'?[{at:w.updated,text:'审核中'}]:[{at:w.updated,text:'评选结果：'+w.status}])];
  modal(isPublic?'公示作品':'参赛作品详情','<div class="work-detail-heading">'+tag(w.track)+(!isPublic?tag(e.status==='已取消'?'赛事已取消':admin?w.status:publicStatus(w)):'')+'<h2>'+esc(w.title)+'</h2><p>'+esc(e.title)+'</p></div>'+(!isPublic?reviewFeedbackHTML(w,admin):'')+(!admin&&!isPublic?extraViews.winner(w,e):'')+(e.status==='已取消'?'<div class="notice danger"><b>赛事已取消</b><span>'+esc(e.cancelReason)+'。已有作品保留，积分由业务人工处理。</span></div>':'')+'<div class="detail-fields"><div><span>作者 / 参赛主体</span><b>'+esc(w.identity.entity)+'</b></div>'+(!isPublic?'<div><span>参赛身份</span><b>'+esc(w.identity.type)+'</b></div><div><span>联系人</span><b>'+esc(w.identity.name)+'</b></div><div><span>联系电话</span><b>'+esc(w.identity.phone)+'</b></div><div><span>联系微信</span><b>'+esc(w.identity.wechat||'—')+'</b></div><div><span>联系邮箱</span><b>'+esc(w.identity.email||'—')+'</b></div>':'')+'</div><h3>作品简介</h3><p class="pre-line">'+esc(w.summary)+'</p><h3>参赛作品</h3>'+filesHTML([...w.files,...(w.projectSnapshot?.file&&!w.files.some(f=>f.id===w.projectSnapshot.file.id)?[w.projectSnapshot.file]:[])])+(w.scriptSnapshot?'<section class="submitted-script"><h3>来源剧本：'+esc(w.scriptSnapshot.title)+'</h3>'+(w.scriptSnapshot.content?'<div class="script-content">'+esc(w.scriptSnapshot.content)+'</div>':'')+filesHTML(w.scriptSnapshot.files||[])+'</section>':'')+(w.project?'<div class="notice">容量万相平台作品：'+esc(w.projectSnapshot?.title||state.projects.find(p=>p.id===w.project)?.title||'演示项目')+'</div>':'')+(!isPublic?'<h3>'+(admin?'处理进度':'参赛进度')+'</h3><ol class="timeline">'+history.slice().reverse().map(h=>'<li><b>'+esc(trackHistoryLabel(h.text))+'</b><small>'+h.at+'</small></li>').join('')+'</ol>':'<p class="muted">作品版权归作者所有。</p>'),button('关闭','close'),true);
}
async function previewFile(id){let f;for(const w of state.works){f=(w.projectSnapshot?.file?.id===id?w.projectSnapshot.file:null)||w.files.find(f=>f.id===id)||w.versions?.flatMap(v=>v.files).find(f=>f.id===id);if(f)break;}if(!f)f=attached.find(f=>f.id===id);if(!f)f=state.projects.flatMap(p=>(p.outputs||[]).map(o=>o.file)).filter(Boolean).find(f=>f.id===id);if(!f)f=[...(state.scripts||[]).filter(s=>s.user==='me').flatMap(s=>s.files||[]),...state.works.flatMap(w=>w.scriptSnapshot?.files||[])].find(f=>f.id===id);if(!f)return;
if(f.demo){modal('示例作品预览',`<div class="sample-document"><span>演示内容 · 非真实参赛文件</span><h2>${esc(f.name.replace(/\.[^.]+$/,''))}</h2><p>第一幕 · 山海之间</p><p>清晨的薄雾沿着山谷散开。年轻的记录者带着一封旧信，走进山脚下的村庄。钟声响起，一段被遗忘的故事重新开始。</p><p>这里展示的是作品预览的交互样式。你上传的真实文件可以在本机查看或下载。</p></div>`,button('关闭','close'));return;}
const blob=await getFile(id);if(!blob){toast('本机文件不存在，请重新上传');return;}const url=URL.createObjectURL(blob),ext=f.name.split('.').pop().toLowerCase();const preview=['mp4','webm','ogg','mov'].includes(ext)?`<video controls src="${url}"></video><p class="muted">如浏览器不支持当前编码，请下载后查看。</p>`:ext==='pdf'?`<iframe class="pdf-frame" title="PDF 作品预览" src="${url}"></iframe>`:`<div class="empty"><span>▤</span><h3>${esc(f.name)}</h3><p>此格式请下载后使用对应应用查看。</p></div>`;modal('参赛文件',preview,`<a class="btn primary" href="${url}" download="${esc(f.name)}">下载文件</a>${button('关闭','close')}`,true);modalCleanup=()=>URL.revokeObjectURL(url);}
function wallet(){modal('我的积分',`<div class="wallet-head"><span>当前可用积分</span><b>${money(state.balance)}</b><small>演示账户 · 不连接真实钱包</small></div>${button('模拟充值','recharge','primary')}<h3>积分明细</h3><div class="ledger-list">${state.ledger.filter(l=>l.user==='me').map(l=>`<div><div><b>${esc(l.kind)}</b><small>${esc(l.note)} · ${l.at}</small></div><strong class="${l.amount>0?'positive':''}">${l.amount>0?'+':''}${money(l.amount)}</strong></div>`).join('')}</div>`,button('关闭','close'));}
function recharge(){modal('模拟积分充值',`<div class="notice">仅演示充值到账流程，不收款、不创建真实订单。套餐及价格待业务配置。</div><form id="recharge-form">${field('充值积分',`<select name="amount">${options(['1000','5000','10000'],'1000')}</select>`)}<div class="form-error"></div><div class="form-actions">${button('取消','close')}<button class="btn primary">确认模拟充值</button></div></form>`);bindForm('recharge-form',d=>{credit(state,{amount:+d.amount,kind:'模拟充值',note:'本地演示，无实际付款'});persist();wallet();render();toast('模拟充值成功');});}
function studioPage(){front('<div class="page-heading"><h1>容量万相漫剧制作</h1></div><p>制作功能由容量万相平台提供，请在新页面打开。</p><a class="btn primary" href="'+STUDIO_URL+'" target="_blank" rel="noopener noreferrer">前往漫剧制作 ↗</a>');}
const ADMIN_TABS=[['events','赛事管理','▦'],['works','参赛作品','▤'],['awards','结果与奖励','♧'],['credits','积分记录','◇']];
function adminShell(page,content){const title=ADMIN_TABS.find(t=>t[0]===page)?.[1]||'赛事管理';document.body.className='admin';app.innerHTML=`<div class="admin-shell"><aside class="admin-sidebar"><a class="admin-brand" href="#/admin/events"><span>RL</span><b>绿台</b></a><div class="side-caption">产品运营</div><div class="admin-group">▣ &nbsp; 内容运营 <span>⌄</span></div><div class="admin-group subtle">AI漫剧官网配置</div><div class="admin-group subtle">生态创新中心</div><div class="sidebar-divider"></div><div class="side-caption">创作大赛</div><nav>${ADMIN_TABS.map(t=>link(`<span>${t[2]}</span>${t[1]}`,'admin/'+t[0],page===t[0]?'active':'')).join('')}</nav><div class="admin-side-bottom"><span class="avatar">容</span><div>容量运营<small>赛事管理员</small></div></div></aside><div class="admin-main"><header class="admin-topbar"><div>☰ <span>内容运营 / 生态创新中心 / <b>创作大赛</b></span></div><span>运营工作台 &nbsp; <i class="avatar">容</i></span></header><div class="admin-tabbar">${title} <span>×</span></div><main class="admin-content"><div class="admin-heading"><div><h1>${title}</h1><p>${{events:'管理合作赛事，配置赛道、征集时间及获奖激励',works:'审核参赛作品，跟进审核结果与评语',awards:'录入线下确认结果，公示获奖名单并跟进奖励履约',credits:'查看积分流水，人工处理赛事赠送与调整'}[page]}</p></div>${page==='credits'?button('＋ 人工调整积分','manual-credit','primary'):''}</div>${content}</main></div></div>${demoBar(true)}`;}
function adminFilters(page,extra=''){return `<form class="admin-filters" id="admin-filters">${field(page==='events'?'赛事名称 / 主办单位':'作品 / 联系人',input('q',filters.q||'','请输入关键词'))}${page!=='events'?field('所属赛事',`<select name="event"><option value="">全部赛事</option>${state.events.map(e=>`<option value="${e.id}" ${filters.event===e.id?'selected':''}>${esc(e.title)}</option>`).join('')}</select>`):''}${extra}<div class="filter-buttons"><button class="btn primary">查询</button>${button('重置','clear-filters')}</div></form>`;}
function bindAdminFilters(){document.querySelector('#admin-filters')?.addEventListener('submit',e=>{e.preventDefault();filters={...Object.fromEntries(new FormData(e.target)),page:1};render();});}
function table(headers,rows){return `<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${headers.length}">${empty('暂无符合条件的数据')}</td></tr>`}</tbody></table></div>`;}
function pagination(total){const page=filters.page||1;return `<div class="pagination"><span>共 ${total} 条</span>${button('‹','page-prev','','aria-label="上一页" '+(page<=1?'disabled':''))}<b>${page}</b>${button('›','page-next','','aria-label="下一页" '+(page*6>=total?'disabled':''))}<span>6 条 / 页</span></div>`;}
function adminEvents(){const filtered=state.events.filter(e=>(!filters.q||(e.title+e.host).includes(filters.q))&&(!filters.status||e.status===filters.status));adminShell('events',`<div class="admin-metrics"><div><span>全部赛事</span><b>${state.events.length}</b></div><div><span>征集中</span><b>${state.events.filter(e=>e.status==='征集中').length}</b></div><div><span>待审核作品</span><b>${state.works.filter(w=>w.status.startsWith('待')&&eventBy(state,w.event).status!=='已取消').length}</b></div><div><span>已公示赛事</span><b>${state.events.filter(e=>e.resultsPublished).length}</b></div></div><div class="admin-card">${adminFilters('events',field('赛事状态',`<select name="status">${options(['草稿','即将开始','征集中','评审中','结果公示','已取消'],filters.status,'全部状态')}</select>`))}<div class="table-title"><h2>赛事列表</h2>${button('＋ 新建赛事','new-event','primary')}</div>${table(['赛事名称','参赛赛道','征集时间','主办单位','状态','作品数','操作'],filtered.slice(((filters.page||1)-1)*6,(filters.page||1)*6).map(e=>`<tr><td><div class="table-event"><img src="./assets/${e.image}" alt=""><div><b>${esc(e.title)}</b></div></div></td><td>${esc(e.tracks.map(trackLabel).join(' / '))}</td><td class="nowrap">${e.tracks[0]?.start}<br>至 ${e.tracks.at(-1)?.end}</td><td>${esc(e.host)}</td><td>${tag(e.status)}</td><td>${state.works.filter(w=>w.event===e.id&&w.status!=='草稿').length}</td><td><div class="table-actions">${button('配置','edit-event','text',`data-id="${e.id}"`)}${e.status==='草稿'?button('发布','publish-event','text',`data-id="${e.id}"`):''}${e.status==='征集中'?button('结束征集','end-event','text',`data-id="${e.id}"`):''}${!['结果公示','已取消'].includes(e.status)?button('取消赛事','cancel-event','text danger-text',`data-id="${e.id}"`):''}</div></td></tr>`))}${pagination(filtered.length)}</div>`);bindAdminFilters();}
function editEvent(id){extraViews.editEvent(id);}
function adminWorks(){const filtered=state.works.filter(w=>w.status!=='草稿'&&(!filters.q||(w.title+w.identity.name+w.identity.phone).includes(filters.q))&&(!filters.event||w.event===filters.event)&&(!filters.status||w.status===filters.status)&&(!filters.track||w.track===filters.track));adminShell('works',`<div class="admin-card">${adminFilters('works',field('作品状态',`<select name="status">${options(['待初审','待复审','已通过','未通过'],filters.status,'全部状态')}</select>`)+field('参赛赛道',`<select name="track">${options(TRACKS,filters.track,'全部赛道')}</select>`))}<div class="table-title"><h2>参赛作品列表</h2><span>审核方式：通过制</span></div>${table(['作品名称','所属赛事 / 赛道','参赛主体','联系人','提交时间','审核状态','操作'],filtered.slice(((filters.page||1)-1)*6,(filters.page||1)*6).map(w=>{const e=eventBy(state,w.event),i=e.tracks.findIndex(t=>t.name===w.track);return `<tr><td><b>${esc(w.title)}</b><small>V${w.version} · ${w.sourceScript?'历史剧本材料':w.project?'漫剧项目':w.files.length?'已上传附件':'未添加作品'}</small></td><td>${esc(e.title)}<small>主办单位：${esc(e.host)}</small><small>${esc(trackTypeLabel(w.track))}</small></td><td>${esc(w.identity.entity)}<small>${esc(w.identity.type)}</small></td><td>${esc(w.identity.name)}<small>${esc(w.identity.phone)}</small></td><td class="nowrap">${w.updated}</td><td>${tag(w.status)}${e.status==='已取消'?'<small class="danger-text">赛事已取消</small>':''}</td><td><div class="table-actions">${button('详情','work','text',`data-id="${w.id}"`)}${w.status.startsWith('待')&&e.status!=='已取消'?button('审核','review','text',`data-id="${w.id}" ${e.status==='征集中'&&TODAY<=e.tracks.find(t=>t.name===w.track).end?'disabled title="该赛道征集截止后开启审核"':''}`):''}</div></td></tr>`;}))}${pagination(filtered.length)}</div>`);bindAdminFilters();}
function reviewModal(id){
  const w=workBy(state,id);
  modal(w.status==='待初审'?'作品初审':'作品复审','<div class="review-target"><span>'+esc(trackTypeLabel(w.track))+' · V'+w.version+'</span><h3>'+esc(w.title)+'</h3><p>'+esc(w.summary)+'</p></div>'+filesHTML(w.files)+(w.project?'<div class="notice">来自万相平台的演示制作作品</div>':'')+'<form id="review-form"><div class="radio-group"><label><input type="radio" name="result" value="通过" checked> 审核通过</label><label><input type="radio" name="result" value="拒绝"> 拒绝</label></div><label class="field"><span id="review-note-label">评语（选填）</span><textarea name="note" rows="5" maxlength="500" placeholder="可填写作品亮点、评价与建议" aria-describedby="review-note-help"></textarea></label><div class="review-note-help"><small id="review-note-help">评语会展示给参赛用户，可在官网「我的赛事」的作品详情中查看。拒绝时必填。</small><span data-note-count>0 / 500</span></div><div class="form-error" role="alert"></div><div class="form-actions">'+button('取消','close')+'<button class="btn primary">确认审核</button></div></form>');
  const form=document.querySelector('#review-form'),note=form.elements.note,label=form.querySelector('#review-note-label'),counter=form.querySelector('[data-note-count]');
  note.addEventListener('input',()=>{counter.textContent=note.value.length+' / 500';});
  form.querySelectorAll('[name="result"]').forEach(r=>r.addEventListener('change',()=>{
    const reject=form.elements.result.value==='拒绝';
    label.textContent=reject?'评语 *':'评语（选填）';note.required=reject;
    note.placeholder=reject?'请说明未通过原因，评语将展示给参赛用户':'可填写作品亮点、评价与建议';
  }));
  bindForm('review-form',d=>{reviewWork(state,id,d.result,d.note);persist();closeModal();render();toast('审核结果已更新，评语同步至参赛用户的作品详情');});
}
function adminAwards(){let eventId=filters.event||'yandang';if(!eventBy(state,eventId))eventId=state.events[0].id;const e=eventBy(state,eventId),awards=state.awards.filter(a=>a.event===eventId);adminShell('awards',`<div class="admin-card"><div class="awards-toolbar">${field('选择赛事',`<select id="awards-event">${state.events.filter(e=>e.status!=='草稿').map(x=>`<option value="${x.id}" ${e.id===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select>`)}<div>${!e.resultsPublished&&e.status!=='已取消'?button('＋ 录入获奖结果','add-award','',`data-event="${e.id}"`)+button('公示结果','publish-results','primary',`data-id="${e.id}"`):tag(e.status)}</div></div><div class="admin-notice">${e.resultsPublished?'结果已公示。获奖名单已锁定，可继续跟进奖励发放。':'请先与主办单位线下确认名次，再录入获奖作品及奖励。公示后官网同步展示，不自动发放积分。'}</div><div class="table-title"><h2>获奖名单与履约</h2><span>${esc(e.host)}</span></div>${table(['获奖作品','参赛主体','奖项','奖励内容','主办方确认','发放进度','操作'],awards.map(a=>{const w=workBy(state,a.work);return `<tr><td><b>${esc(w.title)}</b><small>${esc(trackTypeLabel(w.track))}</small></td><td>${esc(w.identity.entity)}</td><td>${esc(a.rank)}</td><td>${a.cash?'现金 ¥'+money(a.cash)+'<br>':''}${a.credits?money(a.credits)+' 积分<br>':''}${esc(a.goods)}</td><td>${tag(a.confirmed?'已确认':'待确认')}<small>${esc(a.proof||'尚未填写确认记录')}</small></td><td>${a.cash?`<small>现金：${a.cashDone?'已发放':'待发放'}</small>`:''}${a.credits?`<small>积分：${a.creditsDone?'已发放':'待发放'}</small>`:''}${a.goods?`<small>实物：${a.goodsDone?'已发放':'待发放'}</small>`:''}</td><td><div class="table-actions">${!e.resultsPublished?button('编辑','edit-award','text',`data-id="${a.id}"`)+button('移除','delete-award','text danger-text',`data-id="${a.id}"`):button('奖励发放','fulfill','text',`data-id="${a.id}"`)}</div></td></tr>`;}))}</div>`);document.querySelector('#awards-event').onchange=x=>{filters.event=x.target.value;adminAwards();};}
function awardModal(eventId,id=''){const e=eventBy(state,eventId),a=state.awards.find(a=>a.id===id)||{rank:'一等奖',cash:0,credits:0,goods:'',proof:'',confirmed:false};const candidates=state.works.filter(w=>w.event===e.id&&w.status==='已通过'&&!state.awards.some(x=>x.work===w.id&&x.id!==id));modal(id?'编辑获奖结果':'录入获奖结果',`<form id="award-form">${field('获奖作品 *',`<select name="work" required><option value="">请选择审核通过的作品</option>${candidates.map(w=>`<option value="${w.id}" ${a.work===w.id?'selected':''}>${esc(w.title)} · ${esc(trackTypeLabel(w.track))} · ${esc(w.identity.entity)}</option>`).join('')}</select>`)}${field('奖项 / 名次 *',input('rank',a.rank,'如：一等奖、最佳剧本奖',true))}<div class="form-grid">${field('现金奖励（元）',`<input name="cash" type="number" min="0" max="10000000" step="0.01" value="${a.cash}">`)}${field('积分奖励',`<input name="credits" type="number" min="0" max="10000000" step="1" value="${a.credits}">`)}</div>${field('实物奖励',input('goods',a.goods,'如：创作礼盒 × 1'))}${field('线下确认记录',textarea('proof',a.proof,'填写确认单位、时间、对接人及确认依据'))}<label class="check-line"><input name="confirmed" type="checkbox" ${a.confirmed?'checked':''}> 已与主办方线下确认最终结果</label><div class="form-error" role="alert"></div><div class="form-actions">${button('取消','close')}<button class="btn primary">保存结果</button></div></form>`);bindForm('award-form',d=>{if(d.confirmed&&!d.proof.trim())throw Error('已确认结果必须填写线下确认记录');if(!(+d.cash||+d.credits||d.goods.trim()))throw Error('请至少填写一种奖励');if(!candidates.some(w=>w.id===d.work))throw Error('请选择有效的获奖作品');const record={...a,...d,event:eventId,id:id||uid('award'),cash:+d.cash,credits:+d.credits,confirmed:!!d.confirmed};if(id)state.awards[state.awards.findIndex(a=>a.id===id)]=record;else state.awards.push(record);persist();closeModal();render();toast('获奖结果已保存');});}
function fulfillModal(id){const a=state.awards.find(x=>x.id===id),w=workBy(state,a.work);modal('奖励发放',`<h3>${esc(w.title)} · ${esc(a.rank)}</h3><p class="muted">获奖主体：${esc(w.identity.entity)} · 联系人：${esc(w.identity.name)}</p><div class="fulfill-list">${a.cash?`<div><span>现金奖励 <b>¥ ${money(a.cash)}</b></span>${a.cashDone?tag('已完成'):button('登记线下发放','offline-reward','',`data-id="${a.id}" data-kind="cash"`)}</div>`:''}${a.credits?`<div><span>积分奖励 <b>${money(a.credits)} 积分</b></span>${a.creditsDone?tag('已完成'):button('人工发放积分','award-credit','primary',`data-id="${a.id}"`)}</div>`:''}${a.goods?`<div><span>实物奖励 <b>${esc(a.goods)}</b></span>${a.goodsDone?tag('已完成'):button('登记发货','offline-reward','',`data-id="${a.id}" data-kind="goods"`)}</div>`:''}</div><div class="notice">此处仅模拟发放状态。不会实际转账、充值或发送物流订单。</div>${a.cashProof?`<p>现金凭据：${esc(a.cashProof)}</p>`:''}${a.goodsProof?`<p>实物凭据：${esc(a.goodsProof)}</p>`:''}`,button('关闭','close'));}
function adminCredits(){const filtered=state.ledger.filter(l=>(!filters.event||l.event===filters.event)&&(!filters.q||(l.note+l.kind+(l.user==='me'?USER.name:'陈知夏')).includes(filters.q)));adminShell('credits',`<div class="admin-card">${adminFilters('credits')}<div class="admin-notice">报名、赛事取消不会自动赠送或扣回积分。所有调整由业务人员手动处理，并留存操作原因。</div><div class="table-title"><h2>积分流水</h2><span>包含人工赠送、奖励发放、模拟充值及模拟制作消耗</span></div>${table(['操作时间','用户','变动类型','关联赛事','积分变动','操作原因'],filtered.slice(((filters.page||1)-1)*6,(filters.page||1)*6).map(l=>`<tr><td class="nowrap">${l.at}</td><td>${l.user==='me'?USER.name:'陈知夏'}<small>${l.user==='me'?USER.phone:'13900000000'}</small></td><td>${esc(l.kind)}</td><td>${esc(eventBy(state,l.event)?.title||'—')}</td><td><b class="${l.amount>0?'positive':'danger-text'}">${l.amount>0?'+':''}${money(l.amount)}</b></td><td>${esc(l.note)}</td></tr>`))}${pagination(filtered.length)}</div>`);bindAdminFilters();}
function manualCredit(){modal('人工调整积分',`<form id="manual-credit-form"><div class="notice">本地演示仅调整当前体验账户，不连接实际积分系统。</div>${field('用户',`<input value="林予安 · ${USER.phone}" disabled>`)}${field('关联赛事',`<select name="event"><option value="">不关联赛事</option>${state.events.map(e=>`<option value="${e.id}">${esc(e.title)}</option>`).join('')}</select>`)}${field('调整类型',`<select name="direction"><option value="1">赠送积分</option><option value="-1">扣回积分</option></select>`)}${field('积分数量 *',`<input name="amount" type="number" min="1" max="10000000" step="1" required>`)}${field('操作原因 *',textarea('note','','记录赠送、补偿或扣回原因',true))}<p class="muted">当前可用积分：${money(state.balance)}</p><div class="form-error"></div><div class="form-actions">${button('取消','close')}<button class="btn primary">确认调整</button></div></form>`);bindForm('manual-credit-form',d=>{credit(state,{amount:+d.amount*+d.direction,kind:d.direction==='1'?'人工赠送':'人工扣回',note:d.note,event:d.event});persist();closeModal();render();toast('积分已调整，流水已记录');});}
function route(){return location.hash.replace(/^#\//,'').split('?')[0].split('/');}
function render(){const [page,a,b,c]=route();document.title=page==='admin'?'创作大赛管理 · 绿台':'创作大赛 · 容量万相';try{if(page==='event')eventPage(a);else if(page==='mine')minePage();else if(page==='creations'||page==='project'){history.replaceState(null,'','#/events');eventsPage();}else if(page==='submit')submission(a,b,c);else if(page==='edit'){const w=workBy(state,a);if(w)submission(w.event,TRACKS.indexOf(w.track),w.parent,w.id);else front(empty('作品不存在'));}else if(page==='studio')studioPage(a,b||1,c);else if(page==='admin'){({events:adminEvents,works:adminWorks,awards:adminAwards,credits:adminCredits}[a]||adminEvents)();}else eventsPage();}catch(e){console.error(e);app.innerHTML='<div class="empty"><h1>页面暂时无法加载</h1><a href="#/events">返回赛事广场</a></div>';}}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el)return;const {action,id,value}=el.dataset;try{
  if(action==='close')closeModal();
  else if(action==='event-view'){eventView=value;eventsPage();}
  else if(action==='reset')confirm('重置演示数据','只重置本次赛事原型中的示例记录及你在此原型产生的操作，不影响其他原型或真实业务数据。',()=>{state=seed();filters={};},'确认重置');
  else if(action==='event-filter'){filters.status=value;eventsPage();}
  else if(action==='detail-tab'){filters.detail=value;eventPage(route()[1]);}
  else if(action==='mine-filter'){filters.mine=value;minePage();}
  else if(action==='work'||action==='public-work')workModal(id,action==='public-work');
  else if(action==='file')await previewFile(el.dataset.file);
  else if(action==='wallet')wallet();
  else if(action==='recharge')recharge();
  else if(action==='delete-draft')confirm('删除草稿','此草稿尚未提交，删除后将释放一个作品名额。',()=>{const w=workBy(state,id);if(w.status!=='草稿')throw Error('只能删除草稿');state.works=state.works.filter(x=>x.id!==id);},'删除草稿');
  else if(action==='remove-file'){attached.splice(+el.dataset.index,1);document.querySelector('#file-list').innerHTML=filesHTML(attached,true);}
  else if(action==='remove-project'){selectedProject='';selectedOutput='';document.querySelector('#project-selection').innerHTML='';}
  else if(action==='video-source'){switchVideoSource(el.dataset.value);}
  else if(action==='choose-project'){projectQuery='';projectPicker();}
  else if(action==='project-open')projectOutputs(id);
  else if(action==='project-back')projectPicker();
  else if(action==='pick-project'){const p=state.projects.find(p=>p.id===id);if(!p||projectOwner(p)!=='me'||!platformOutputs(p).some(o=>o.id===el.dataset.output))throw Error('请选择本人的已完成视频');selectedProject=id;selectedOutput=el.dataset.output;closeModal();document.querySelector('#project-selection').innerHTML=projectSelection();}
  else if(action==='consult')extraViews.consult(eventBy(state,id));
  else if(action==='terms')modal('参赛声明',`<div class="terms"><h3>作品版权归作者所有</h3><p>你确认提交的作品为本人原创，或已取得足以参加本赛事的授权，且不侵犯他人的合法权益。</p><h3>评审与公示</h3><p>你同意容量及主办单位为赛事评审使用本次提交的材料，并在赛事公示页展示通过评审的作品、作者名称及获奖信息。联系电话、微信、邮箱等个人信息不对外公开。</p><h3>费用与奖励</h3><p>参赛免费。漫剧制作所需积分与赛事奖励分别处理；赛事取消不自动返还或赠送积分，具体处理由运营联系确认。</p><small class="muted">当前为产品原型声明示例，正式条款及公开范围需业务确认。</small></div>`,button('我知道了','close'));
  else if(action==='new-event')editEvent();else if(action==='edit-event')editEvent(id);
  else if(action==='clear-filters'){filters={};render();}
  else if(action==='page-prev'||action==='page-next'){filters.page=(filters.page||1)+(action==='page-next'?1:-1);render();}
  else if(action==='publish-event')confirm('发布赛事','发布后赛事将出现在官网。不会自动赠送积分。',()=>{const e=eventBy(state,id);if(e.status!=='草稿')throw Error('赛事已发布');validateEvent(e);e.status=e.tracks.every(t=>TODAY<t.start)?'即将开始':e.tracks.every(t=>TODAY>t.end)?'评审中':'征集中';},'确认发布');
  else if(action==='end-event')confirm('结束赛事征集','结束后不再接受新投稿或作品修改，已提交作品继续审核。',()=>{eventBy(state,id).status='评审中';},'结束征集');
  else if(action==='cancel-event'){modal('取消赛事',`<form id="cancel-event-form"><div class="notice danger">取消后停止投稿、制作入口参赛及审核；保留已有作品。积分不会自动处理。</div>${field('取消原因 *',textarea('reason','','原因将展示给参赛用户',true))}<div class="form-error"></div><div class="form-actions">${button('暂不取消','close')}<button class="btn danger-btn">确认取消赛事</button></div></form>`);bindForm('cancel-event-form',d=>{cancelEvent(state,id,d.reason);persist();closeModal();render();toast('赛事已取消');});}
  else if(action==='review')reviewModal(id);
  else if(action==='add-award')awardModal(el.dataset.event);
  else if(action==='edit-award'){const a=state.awards.find(a=>a.id===id);awardModal(a.event,id);}
  else if(action==='delete-award')confirm('移除获奖结果','移除此条未公示的获奖结果，不删除参赛作品。',()=>{state.awards=state.awards.filter(a=>a.id!==id);},'确认移除');
  else if(action==='publish-results')confirm('公示赛事结果','请确认已与主办单位线下确认全部名次。公示后名单锁定，通过审核的作品将公开，赛事停止接收投稿；不会自动发放奖励。',()=>publishResults(state,id),'确认公示');
  else if(action==='fulfill')fulfillModal(id);
  else if(action==='award-credit')confirm('人工发放奖励积分','将积分记入获奖用户的演示账户并记录流水，重复点击不会重复发放。',()=>{const a=state.awards.find(a=>a.id===id),w=workBy(state,a.work);credit(state,{user:w.user,amount:a.credits,kind:'赛事奖励',note:a.rank+' · '+w.title,event:a.event,award:a.id});a.creditsDone=true;},'确认模拟发放');
  else if(action==='offline-reward'){const kind=el.dataset.kind;modal(kind==='cash'?'登记现金发放':'登记实物发货',`<form id="offline-form">${field(kind==='cash'?'转账记录 / 凭据 *':'物流公司 / 运单号 / 发放记录 *',textarea('proof','','请输入线下履约记录',true))}<div class="notice">仅登记线下处理结果，不实际发起付款或物流订单。</div><div class="form-error"></div><div class="form-actions">${button('取消','close')}<button class="btn primary">确认已发放</button></div></form>`);bindForm('offline-form',d=>{const a=state.awards.find(a=>a.id===id);a[kind+'Done']=true;a[kind+'Proof']=d.proof;persist();closeModal();render();toast('发放记录已保存');});}
  else if(action==='manual-credit')manualCredit();
}catch(e){toast(e.message);}});
root.addEventListener('click',e=>{if(e.target.classList.contains('overlay'))closeModal();});
document.addEventListener('keydown',e=>{if(!root.innerHTML)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const focusable=[...root.querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>{closeModal();filters={};render();window.scrollTo(0,0);});
window.addEventListener('storage',e=>{if(e.key===KEY){state=load();if(!['submit','edit'].includes(route()[0])&&!root.innerHTML)render();else toast('演示数据已在另一页面更新');}});
function projectPicker(){
  const projects=state.projects.filter(p=>projectOwner(p)==='me'&&isPlatformProject(p)),shown=projects.filter(p=>p.title.toLowerCase().includes(projectQuery.toLowerCase()));
  modal('选择容量万相平台作品','<p class="muted">展示你在容量万相创建的全部项目。进入项目后选择已完成的视频作品。</p><form id="project-search" class="project-search"><input name="q" placeholder="搜索项目名称" value="'+esc(projectQuery)+'"><button class="btn">搜索</button></form><p class="muted">共 '+projects.length+' 个项目</p><div class="project-picker">'+shown.map(p=>'<button type="button" data-action="project-open" data-id="'+p.id+'"><img src="./assets/'+(p.image||'studio.jpg')+'" alt="项目封面"><div><b>'+esc(p.title)+'</b><small>'+p.created+'</small><small>'+(platformOutputs(p).length?'已完成 · '+platformOutputs(p).length+' 个视频可选':'创作中 · 暂无可提交视频')+'</small></div><i>查看项目 →</i></button>').join('')+(shown.length?'':'<p class="empty">没有找到符合条件的项目</p>')+'</div>',button('取消','close'),true);
  document.querySelector('#project-search').onsubmit=e=>{e.preventDefault();projectQuery=new FormData(e.target).get('q').trim();projectPicker();};
}
function projectOutputs(id){
  const p=state.projects.find(p=>p.id===id&&projectOwner(p)==='me'&&isPlatformProject(p));if(!p)return;
  modal('选择项目中的作品','<div class="project-output-head"><img src="./assets/'+(p.image||'studio.jpg')+'" alt="项目封面"><div><h3>'+esc(p.title)+'</h3><p>容量万相平台项目 · '+p.created+'</p></div></div>'+(platformOutputs(p).length?'<div class="project-picker">'+platformOutputs(p).map(o=>'<button type="button" data-action="pick-project" data-id="'+p.id+'" data-output="'+o.id+'"><span>▷</span><div><b>'+esc(o.title)+'</b><small>'+esc(o.duration)+' · 已完成 · 演示视频记录</small></div><i>选择此作品 →</i></button>').join('')+'</div>':'<div class="empty"><h3>该项目暂无已完成的视频</h3><p>完成制作并导出视频后，再返回这里选择。</p><a class="btn" href="'+STUDIO_URL+'" target="_blank" rel="noopener noreferrer">前往漫剧制作 ↗</a></div>'),button('返回项目列表','project-back')+button('取消','close'),true);
}
const extraViews=createEventViews({getState:()=>state,esc,money,button,field,input,textarea,options,modal,bindForm,closeModal,persist,render,toast});

render();
